import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inversion of only two readonly predicates and their private pure helper. */
public final class SourceReadonlyInventoryOriginDelta {
 static final String REPO="local/lito381/server/LegacyMySqlRepository",HELPER="nativeSourceOwnedInventoryMode";
 static void need(boolean value,String label){if(!value)throw new AssertionError(label);}
 public static void main(String[]a)throws Exception{int calls=0;try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var old=FreezeSourceTargetDelta.read(base,REPO);var now=FreezeSourceTargetDelta.read(jar,REPO);need(old.fields.size()==now.fields.size()&&now.methods.size()==old.methods.size()+1,"no field or existing method schema change");for(int i=0;i<old.fields.size();i++){var x=old.fields.get(i);var y=now.fields.get(i);need(x.access==y.access&&x.name.equals(y.name)&&x.desc.equals(y.desc)&&Objects.equals(x.value,y.value),"every original field");}
  for(var method:old.methods){var actual=now.methods.stream().filter(m->m.name.equals(method.name)&&m.desc.equals(method.desc)).findFirst().orElseThrow();for(var node:actual.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(REPO)&&call.name.equals(HELPER)){need(method.name.equals("sourceInventorySql"),"only existing inventory SQL origin predicates");var read=FreezeAcceptedMethods.prev(call);var receiver=FreezeAcceptedMethods.prev(read);need(read instanceof FieldInsnNode f&&f.getOpcode()==GETFIELD&&f.owner.equals(REPO)&&f.name.equals("readOnly")&&receiver instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==0,"original immutable readonly flag");actual.instructions.remove(read);actual.instructions.remove(receiver);call.owner="java/lang/String";call.name="equals";call.desc="(Ljava/lang/Object;)Z";call.setOpcode(INVOKEVIRTUAL);calls++;}need(Arrays.equals(FreezeSourceTargetDelta.body(old,method,method.name,method.access),FreezeSourceTargetDelta.body(now,actual,method.name,method.access)),"every original method inverse "+method.name);}
  var helper=now.methods.stream().filter(m->m.name.equals(HELPER)).findFirst().orElseThrow();need(helper.access==(ACC_PRIVATE|ACC_STATIC)&&helper.desc.equals("(Ljava/lang/String;Ljava/lang/Object;Z)Z"),"private pure predicate only");var ops=new ArrayList<Integer>();for(var node:helper.instructions)if(node.getOpcode()>=0)ops.add(node.getOpcode());need(ops.equals(List.of(ILOAD,IFEQ,ICONST_0,IRETURN,ALOAD,ALOAD,INVOKEVIRTUAL,IRETURN)),"pure readonly then original String.equals");need(calls==2,"two origin branches only");var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var following=jar.getJarEntry(e.getName());need(following!=null,"retained entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(following).readAllBytes()))changed.add(e.getName());}for(var e:Collections.list(jar.entries()))need(names.contains(e.getName()),"no new class/authority");need(changed.equals(Set.of(REPO+".class")),"one original repository class");
 }System.out.println("PASS independent archive/schema/all-original-method inverse; only two readonly-origin predicates, pure helper, no new SQL or persistence authority");}
}
